skin.stylesheet:
		/* ========================================================== *

		 	WELCOME TO TRENCH 

 * ========================================================== *
			  skin by danni
 * ========================================================== */


html { overflow-x: auto; } 
form { display:inline; }

/****************************************
 Body Background & Text Style
*****************************************/

body { 
	font: normal 400 12px/16px montserrat; 
	color: rgba(var(--ltbase),1); margin:0px;
	padding:0px;
        background: rgba(42,42,42,1); 
	background-image: url(https://imagizer.imageshack.com/img923/9525/urJkXo.png);
	text-align:center;
        background-repeat: no-repeat;
 	background-size: cover;
	background-attachment: fixed;

}

::-webkit-scrollbar {
  display: none
}

/***=============================
	BOARD COLORS
=============================***/

:root {
  --btaccent: 103, 153, 116;
  --dnaccent: 98, 98, 98;
  --dkbase: 0, 0, 0;
  --ltbase: 255, 255, 255; 
}


/***=============================
	MEMBER COLORS
=============================***/


/* guest color */

#mg-2, .mg-2 {
  --mg: 103, 153, 116;}


/* member color */

#mg-3, .mg-3 {
  --mg: 103, 153, 116;}


/* admin color */

#mg-4, .mg-4 {
  --mg: 0, 179, 179; } 



/* banned color */

#mg-5, .mg-5 {
  --mg: 103, 153, 116; } 



/* criminals color */

#mg-6, .mg-6 {
  --mg: 55, 112, 142;}


/* enforcers color */

#mg-7, .mg-7 {
  --mg: 142, 134, 55;}

/* civilians color */

#mg-8, .mg-8 {
  --mg: 111, 83, 130;}


/* alias color */

#mg-9, .mg-9 {
  --mg: 168, 62, 50;}




/****************************************
  	 Table Styles
*****************************************/

table, tr, td {
	font-family: Arial, sans-serif; 
	font-size: 12px; 
	color: rgba(var(--ltbase),1); 
}

.forum-subheader { display: none; }

/****************************************
   Board Width
*****************************************/

#iikmwrapper { 
   width: 1320px;
   position: relative;
   margin: 0px auto;
}

#wrapper { 
	text-align:left;
        width: 1040px;
        padding: 15px;
	margin: 0px 0px 30px 280px;
}

#innerwrapper { 
	padding: 0 10px;
}

/****************************************
   Link colors
*****************************************/

a:link, a:visited, a:active { 
	text-decoration: none;
	color: rgba(var(--btaccent),1);

}
a:hover { 
	color: rgba(var(--ltbase), 1); 
	text-decoration: none; 
}


/****************************************
   Profile styles 
*****************************************/

#profilename { 
	font-size:28px;
	font-weight:bold; 
}

#photowrap { 
	padding:6px; 
}

#phototitle { 
	font-size:24px; 
	border-bottom:1px solid black;
}

#photoimg   { 
	text-align:center; margin-top:15px; 
} 

/****************************************
   UserCP/My Controls styles
*****************************************/

#ucpmenu { 
	line-height:150%;
	width:22%; 
	border:1px solid rgba(var(--ltbase),1);
  	background: rgba(var(--dkbase), .6); 
	color: rgba(var(--ltbase),1);
}

#ucpmenu p  { 
	padding:2px 5px 6px 9px; 
	margin:0px;  
}

#ucpcontent { 
	background-color: transparent; 
	border:1px solid rgba(var(--ltbase),1);
	line-height:150%; width:auto; 
	background: rgba(var(--dkbase), .6); 
	color: rgba(var(--ltbase),1);
}

#ucpcontent p  { 
	padding:10px;
	margin:0px; 
}


#field-website, #field-location, #field-interests {
display: none;
}


/****************************************
  Logo Strip
*****************************************/

#logostrip { 
	display: none;
}

/****************************************
  Search Bar 
*****************************************/

#searchbar {
	display: none;	
	float: right;
	position: relative;
	right: 10px;
	top: 8px;
}

#searchbar .search-container {
    background-color: rgba(var(--ltbase),1);
    box-shadow: 0 1px 3px rgba(var(--dkbase),0.4) inset;
    border: 1px solid rgba(var(--dkbase), 1);
    display: block;
    height: 26px;
    position: relative;
    width: 200px;
}

#searchbar .search-input {
	background: none repeat scroll 0 0 transparent;
	border: 0;
	color: rgba(var(--dkbase), 1);
	font-size: 12px;
	width: 192px;
	height: 26px;
	font-family: oswald;
	padding: 1px 0 0 8px;
}

#searchbar .search-input:focus {
    color: rgba(var(--dkbase),1);
}

#searchbar .search-button {
	border: 0;
	bottom: 0;
	margin: 0;
	border-radius: 0;
	display: block;
	height: 26px;
	padding: 0;
	position: absolute;
	right: 0;
	text-indent: -3000em;
	top: 0;
	width: 26px;
	cursor: pointer;
	box-shadow: none;
}

/****************************************
  Navigation Bar / Submenu
*****************************************/

#submenu  {
	display: none;
}

#submenu img { 
	display: none; 
}

#submenu a:link, #submenu a:visited, #submenu a:active { 
	text-decoration: none;
	color: rgba(var(--ltbase),1) !important; 
        padding: 7px 7px;
        font-weight: bold;
}

#submenu a:hover { 
	color: rgba(var(--ltbase),1) !important; 
	text-decoration: underline; 
}

#navi br { 
	display: none; 
}

#navstrip  { 
	font-weight:bold;
	padding: 5px 0px; 

}

/****************************************
   Calendar styling
*****************************************/

.caldate   { 
	text-align:right;
	font-weight:bold;
	font-size:11px;
	color:#555;
	background-color:#F2F2F2;
	padding:4px; margin:0px; 
}

#calendarname { 
	font-size:22px;
	font-weight:bold; 
}

#padandcenter { 
	margin-left:auto;
	margin-right:auto;
	text-align:center;
	padding:14px 0px 14px 0px; 
}


/**************************************************
 User Links Menu (Messages / View new posts / etc )
***************************************************/

#userlinks { 
	display: none;
}

#userlinks td { 
	color: #333; 
}

#userlinks a { 
	text-decoration: underline; padding: 1px; 
}

#userlinks a:hover { 
	text-decoration: none; 
}


/****************************************
   Topic View styles
*****************************************/

.activeuserstrip { 
	background: rgba(var(--dkbase), .8);
	padding:6px;
}

.normalname { 
	display: none;
}


.unreg { 
	font-size: 11px; 
	font-weight: bold; 
	color: #900; 
}

.post1 { 
	background-color: rgba(var(--dkbase),1); 
}

.post2 { 
	background-color: rgba(var(--dkbase),1); 
}

.postdetails { 
	font-size: 10px; 
}

.postcolor   { 
	font-size: 12px; line-height: 160%; 
}

.postlinksbar {
	width: 100%;
	padding: 5px 15px;
	margin: 10px 0px;
}


.postlinksbar a {
	background: rgba(var(--btaccent),.8);
	border-radius:3px;
	color: rgba(var(--ltbase),1);
	font-size: 12px;
	font-weight: 600;
	margin: 3px;
	padding: 10px;
	text-decoration: none;
	border: none; 
        min-width: 75px;
        display: inline-block;
	text-align: center;
}

.signature   { 
	font-size: 10px; 
	color: #339; 
	line-height:150%;  
}


/*******************************
 Pagination e.g. [1],2,3 ...
*******************************/

.pagination .pagination_current, .pagination a {
     padding: 2px 5px;
}

.pagination a:link, .pagination a:visited, .pagination a:active {
     border: 1px solid #800000;
     border-radius:3px;
     background-color:#740300;
     padding-left:6px;
     padding-right:6px;
     color:rgba(var(--ltbase),1);
     text-decoration:none;
     box-shadow: 0pt 2px 3px rgba(var(--dkbase),0.4);
}

.pagination a:hover {
	background: rgba(var(--btaccent),1);
	text-decoration: none;
	color: rgba(var(--dkbase),1);
	box-shadow: 0pt 2px 3px rgba(var(--dkbase),0.4);

}

.pagination .pagination_current {
     background: none repeat scroll 0% 0% rgba(var(--ltbase),1);
     border: 1px solid #545454;
     border-radius:3px;
     padding-left:6px;
     padding-right:6px; 
}

.pagination_first, .pagination_last, .pagination_page {
     background: none repeat scroll 0% 0% #740300;
     border: 1px solid #800000;
}

.pagination_pagetxt {
    display:none;
}

/****************************************
   Global general table/div row styles
*****************************************/

.row1, .row3 { 
	background: rgba(var(--dkbase), .4);
	padding: 5px;
	color: rgba(var(--ltbase),1); 

}

.row4, .row2 { padding: 5px; }


#boardstats .row2 { 
	text-align: center; 

}

.darkrow1 { 
	background: rgba(var(--dnaccent),1); 
	color: rgba(var(--dkbase),1); 
}

.darkrow2 { 
	 color: rgba(var(--dkbase),1); 
}

td.darkrow2 { 
	display: none; 
}

.darkrow3 { 
	background: rgba(var(--dnaccent),1); 
	color: rgba(var(--dkbase),1); 
	padding: 3px; 
}

.hlight, .dlight { background: rgba(var(--dkbase), .4); color: rgba(var(--ltbase), 1); }


.tablebasic {
	background: rgba(var(--dkbase), .8);
}

/****************************************
   Top table bars / gradient holders 
*****************************************/

.maintitle { 
	text-decoration: none; 
	color: rgba(var(--btaccent),1);
        text-shadow: 2px 2px 2px rgba(var(--dnaccent),.85);
	margin-top:1px; 
 	padding: 40px;
	text-transform: lowercase;
	font: normal 400 60px/60px barrio;
	text-align: center; !important; 
	background: rgba(var(--dkbase), .8);
	border-radius: 10px;

}

.maintitle a:link, .maintitle  a:visited, .maintitle  a:active { 
	text-decoration: none; 
	color: rgba(var(--btaccent),1);
}


.maintitle a:hover { 
	color: rgba(var(--ltbase),1)
	text-decoration: none;  
}

/****************************************
  Bar directly below the maintitles 
*****************************************/

.titlemedium { 
	font-weight:bold; 
	padding: 2px 6px; margin:0px;
	background: rgba(var(--dnaccent), 1);
	font: normal normal normal 13px/20px montserrat;
	color:rgba(var(--ltbase),1);
	text-align: center;
 }

.titlemedium  a:link, .titlemedium  a:visited, .titlemedium  a:active  { 
	text-decoration: none; 
	color: rgba(var(--btaccent), .8); 
}

/****************************************
  Table & Div Borders 
*****************************************/

.tableborder { 

padding:0px; margin:0; 
}

.tablefill { 

	border:1px solid #555; 
	padding:6px; 
}

.tablepad {

	padding:6px;
}

.tablebasic {
	width:100%; padding:0; margin:0px; border:0px; 
}

.plainborder { 
	border:1px solid #555; 

}

/****************************************
  QUOTE and CODE BBCode boxes
*****************************************/

#QUOTE { 
	white-space: normal; 
	font-family: montserrat;
	font-size: 13px; 
	padding:10px;
	border: 1px solid rgba(var(--mg),1); 
	margin-top: 2px; 
}

/****************************************
CODE AREA CSS
*****************************************/

#CODE  {
white-space:normal;
font-family: montserrat; 
font-size: 12px;
padding: 10px;
margin-top:2px;
     word-break: break-word;
}

.code-scroll {
max-height: 250px;
overflow: auto;
padding-right: 5px;
}


.code-top {
background-color:rgba(var(--mg),0.5); 
margin: 0;
padding: 0;
text-align: center;
overflow: hidden;
color: rgba(var(--ltbase),1);
}

.code-highlight {
font: normal normal normal 8px/100% montserrat;
color:rgba(var(--mg),1);
padding: 4px 6px 2px; margin:0px;
background-color:rgba(var(--ltbase),1);
text-align: center;
text-transform: uppercase;
letter-spacing: 1px;
cursor: crosshair;
}

.code-top .code-title {
margin: 20px;
font: italic normal 300 20px/100% montserrat;
text-transform: lowercase;
}

.code-toggle {
cursor: crosshair;
}

.code-scroll.auto-code {
height: auto;
max-height: none;
}

#CODE-WRAP.nicole-code { border-collapse: collapse; }

/**********************************************
  Input buttons, e.g. submit, text input, etc
***********************************************/

.button-large {
	background: rgba(var(--btaccent),.8);
	border-radius:3px;
	color: rgba(var(--ltbase),1);
	font-size: 12px;
	font-weight: 600;
	margin: 3px;
	padding: 10px;
	text-decoration: none;
	border: none; 
        min-width: 75px;
        display: inline-block;
	text-align: center;
}


.button-small {
	background: rgba(var(--btaccent),.8);
	border-radius:3px;
	color: rgba(var(--ltbase),1);
	font-size: 10px;
	font-weight: 500;
	margin: 3px;
	padding: 10px;
	text-decoration: none;
	border: none; 
        min-width: 50px;
        max-width: 80px;
	text-align: center;
}

.post-buttons-top { margin-top: 3px; }

.button-large.closed {
	display: nonse;
}

.forminput, .codebuttons, .textinput, .radiobutton, .checkbox {
	border-radius: 10px;
	background: rgba(var(--dnaccent),.8);
	border: 1px solid rgba(var(--ltbase),1);
	color: rgba(var(--ltbase),1);
	font-family: montserrat, sans-serif;
	font-size: 12px;
	padding: 10px;
	vertical-align: middle;
}


input[type=submit], input[type=button], input[type=reset] {
	background: rgba(var(--btaccent),.85);
	border-radius:3px;
	color: rgba(var(--ltbase),1);
	font-size: 12px;
	font-weight: bold;
	margin: 3.5px;
	padding: 10px;
	text-decoration: none;
	border: none; 
	text-transform: lowercase;
}

.codebuttons  { 
	font-size: 10px; 
}


/****************************************
  Form table cell styles, left/right/top
*****************************************/

.pformstrip {
	background-color: rgba(var(--dnaccent),.85);
	color: rgba(var(--ltbase),1);
	height: 40px;
	margin-top:1px; 
 	padding: 10px;
	text-transform: lowercase;
	font: normal 500 14px/20px montserrat;
	text-align: center;
}

.pformleft  { 
	background: rgba(var(--dkbase),.85);
	color: rgba(var(--ltbase), 1);
	padding:6px; 
	margin-top:1px; width:25%;  
}

.pformleftw { 
	background-color: rgba(var(--dkbase), .45); 
	padding:6px; 
	margin-top:1px;width:40%; 
	border-top:1px solid rgba(var(--dnaccent),.85); 
	border-right:1px solid rgba(var(--dnaccent),.85); 
}

.pformright { 
	background-color: rgba(var(--dkbase), .45);
	color: rgba(var(--ltbase), 1);
	padding:6px; margin-top:1px;
	border-top:1px solid  rgba(var(--dnaccent),.85);
}

.topic-subheader, .wrapmini { display: none; }

#modcp-content { background: rgba(var(--dkbase), .6); }



/****************************************
 Tabs on the portal profiles + sections
*****************************************/

.opentab {
	color: rgba(var(--ltbase),1);
	padding:8px;float: left; width: auto;
	background-color: #800000;
	margin-top:3px;
	margin-right:2px;
	font-size:11px;
	border: #545454 1px solid;	
}

.closedtab {
	color: rgba(var(--ltbase),1);
	padding:7px;float: left;width: auto;
	background-color: #800000;

	margin-top:6px;
	margin-right:2px;
	font-size:11px;
	border-top:   #545454 1px solid;
	border-right: #545454 1px solid;
	border-left:  #545454 1px solid;
}

.positiontab { 
	height: 34px; margin-left: 2px;
}

/****************************************
   Delete all cookies / mark read
*****************************************/

#delcookiesrow, #mark-as-read-subto {
	background-color: transparent;
	border-bottom: 1px solid rgba(var(--ltbase),1);
	font-size: 11px;
	padding: 5px;
        width: 350px;
        float: right;
        margin-top:15px;
        padding-left:1px;
}

#mark-as-read-subto {
	float: none;
	padding-top: 3px;
}


/*******************************
     Board Statistics Links
*******************************/

.toplinks a {
	color: rgba(var(--ltbase),1);
	font-size: 11px;
	text-decoration: none;
}

.toplinks {
	margin: 0 11px -37px 0;
	text-align: right;
	color: transparent;
}

/*******************************
 Mini Profile Seperators
*******************************/

.postbit { 
	border-bottom: solid 1px #C0C0C0; 
	color: black;
	background: #EFEFEF;
	font-size: 11px;
        padding: 6px 7px;
}

/********************************
	Miscellaneous
********************************/

/* image tag styles */
img        { vertical-align:middle; border:0px }
img.attach { border:2px outset #555;padding:2px }

/* Forum Descriptions */
.desc { font-size:11px; color: rgba(var(--dkbase),1); }

/* Edited by text */
.edit { font-size: 9px }

/* Topic Macros */

.wrapmini { float: left; }

/* Warning CSS */
.warngood { color:green }
.warnbad  { color:red }

/* Skin selector dropdown */
#skin_selector { 
	margin: 10px 0; 
}


/* Online users list row */
.thin { 
	padding:6px 0px 6px 0px;
	line-height:140%;
	margin:2px 0px 2px 0px;
	border-top:1px solid #545454;
	border-bottom:1px solid #545454;
}

/* Latest news area */
.newstext { 
	display: none;
}

/* Highlighted text in search */
.searchlite { 
	color:#F00;
	font-weight:bold;  
	background-color:#FF0; 
}

/****************************************
 Mobile-specific Styles
*****************************************/

#mobile { 
	background-color: #FBFBFB;
}

/***********************************
 Copyright: Removal is against Terms
************************************/

.copyright { 
	font-size: 10px; line-height: 12px; 
}


/*=========================================================
  =========================================================
		Danni's Custom Codes
  =========================================================
  =========================================================*/


/****************************************
	CUSTOM MINI PROFILE
****************************************/
/*******don't touch this unless you make the middle section of the mini taller. if you do, change the min-height to whatever to appropriate height would be*******/

#outerpost {
position:relative;
min-height: 600px!important;
}

/****this makes space for the top and bottom info bars******/

.borderout {
padding-top:180px;
}



/*******this is inside the HTML profile template. any heights or margins you change in the top and bottom info bars must be reflected in the padding of the above .borderout class*******/


.outertopmini {
width:1020px;
position: absolute;
height:180px;
top:-190px;
left: -10px;
}

.outerbottommini {
width:1020px;
position: absolute;
left: 0px; 
bottom: -15px;
height: 5px;
  margin-bottom: 50px;  
}

/*******this is your middle mini section. any changes to width needs to be reflected in both of these classes– any changes to height must be reflect in the #outerpost min-height******/

.miniprofilepost {
   width:250px;
   padding-left: 10px;
}

.insidemiddlemini {
	width:250px;
	height:400px;
	position: absolute;
	right: 0px;
}


/***************************
 Board Stats
**************************/

.recent-topics-date { display: none; }


#wttbsframe {
  width: 1000px;
  min-height: 265px;
  padding: 10px;
  background: rgba(var(--dkbase), 0.6);
  position: relative;
  border: 2px solid rgba(var(--ltbase), 1);
}

.wttbshead {
  width: 100%;
  height: 75px;
  position: absolute;
  left: 0px;
  top: 0px;
  background: rgba(var(--dkbase), .8);
}

.wttbsavbox {
  width: 75px;
  height: 75px;
  position: absolute;
  left: 0px;
  top: 0px;
  background: rgba(var(--btaccent), .8);
}

.wttbsavbox mac {
  width: 60px;
  height: 60px;
  border: 2px rgba(var(--ltbase), 1) solid;
  border-radius: 100%;
  position: absolute;
  top: 5px;
  left: 5px;
  overflow: hidden;
  font: normal 400 33px/60px oswald;
  text-align: center;
  background: rgba(var(--dkbase), .8);
  color:  rgba(var(--btaccent), 1);
}

.wttbslink {
  width: 35px;
  height: 35px;
  background: rgba(var(--dnaccent), .8);
  border-radius: 100%;
  position: relative;
  float: right;
  color: rgba(var(--ltbase), 1);
  font: normal 400 18px/35px oswald;
  text-align: center;
  margin: 30px 5px 0px;
}

.wttbslink:hover {
    background: rgba(var(--btaccent), .8);
}

.wttprhdtx {
  position: absolute;
  top: 0px;
  left: 75px;
  padding: 5px 15px;
  font: normal 500 30px/65px oswald;
  text-align: left;
  text-transform: uppercase;
  color: rgba(var(--ltbase), 1);

}

.wttbsbar {
  width: 1000px;
  height: 20px;
  padding: 0px 10px;
  position: absolute;
  left: 0px;
  top: 75px;
  background: rgba(var(--dnaccent), .8);
  color: rgba(var(--ltbase), 1);
  font: normal 600 10px/20px Montserrat;
  text-align: left;
  text-transform: uppercase;

}

.wttbsbar b { 
  color: rgba(var(--btaccent),1);
}

.wttbsdeet {
  padding: 10px;
  background: rgba(var(--dnaccent), .8);
  border: 1px solid rgba(var(--btaccent), .4);
  position: absolute;
  color: rgba(var(--ltbase), 1);
  text-transform: uppercase;

}

.wttbsdeet b {
  font-weight: normal;
  display: block;
  position: absolute;
  top: -10px;
  left: 5px;
  padding: 3px 5px;
  background: rgba(var(--btaccent), .75);
  z-index: 80;
  font: normal 600 11px/12px Montserrat;
}

.wttbsdt {
  width: 100%;
  height: 100%;
  overflow: scroll;
  overflow-x: hidden;
  text-align: justify;
  font: normal 600 11px/13px Montserrat;
}

.wttbsdt::-webkit-scrollbar {
  width: 0px;
}

.wttbson {
  width: 300px;
  height: 50px;
  top: 110px;
  left: 10px;
}

.wttbsot {
  width: 300px;
  height: 50px;
  top: 200px;
  left: 10px;
}

.wttbsnm {
  width: 290px;
  height: 20px;
  top: 110px;
  left: 345px;
  text-align: right;
  font: normal 600 15px/20px Montserrat;
}

.wttbstp {
  width: 290px;
  height: 20px;
  top: 170px;
  left: 345px;
  text-align: right;
  font: normal 600 14px/20px Montserrat;
}

.wttbstm {
  width: 290px;
  height: 20px;
  top: 230px;
  left: 345px;
  text-align: right;
  font: normal 600 14px/20px Montserrat;
}

.wttbsrt {
  width: 320px;
