  color: rgba(var(--ltbase),1);
}

#wttnavbar .forminput {
	background: rgba(var(--dnaccent),.6);
	border: 0px;
	color: rgba(var(--ltbase),1);
	font-family: montserrat, sans-serif;
	font-size: 10px;
	padding: 2px;
	vertical-align: middle;
	float: right;
	border-radius: 0px;
	margin: -40px 20px auto 0px;
}



/*************************** SIDEBAR ***************************/

#iikmsidebar {
  width: 260px;
  height: 520px;
  position: absolute;
  top: 500px;
  left: 0px;
  border: 2px rgba(var(--ltbase),1) solid;
  background: rgba(var(--dkbase),.8);
}


.iikmstat {
  width: 216px;
  height: 21px;
  padding: 5px;
  margin: 5px 15px;
  background: rgba(var(--ltbase),1);
  position: relative;
  border: 2px solid rgba(var(--mg),1);  


}

.iikmstatnbox {
  width: 35px;
  height: 35px;
  top: -2px;
  position: absolute;
  background: rgba(var(--mg),1);
  font: normal 400 13px/35px oswald; 
}

.iikmstatnum {
  width: 15px;
  height: 15px;
  background: #fff;
  padding: 5px;
  margin: 5px;
  line-height: 15px;
  text-align: center;
  border-radius: 100%;
  color: rgba(var(--mg),1);


}

.iikmstattx {
  width: 178px;
  height: 21px;
  padding: 5px;
  top: 0px;
  position: absolute;
  background: rgba(var(--ltbase),1);
  color: rgba(var(--mg),1);
  font: normal 600 13px/21px montserrat; 
  letter-spacing: 2px;
}

.iikmtabs {
position: relative;  
width: 250px;
height:  375px;
margin: 0px 5px;
}

.iikmtab {
float: right;

}

.iikmtab label {
background: rgba(var(--dnaccent),1);
padding: 10px;
position: absolute;
border-radius: 3px;
  top: 0px;
   width: 50px;
  height: 15px;
  line-height: 15px;
  text-align: center;
  font: normal 600 17px/15px montserrat; 

}

.iikmtab [type=radio] {
display: none;  
}

.iikmcontent {
position: absolute;
top: 35px;
bottom: 0px;
left: 0px;
right: 0px;
background: rgba(var(--dkbase),1);
padding: 10px;
text-align: left;

}

.iikmtab [type=radio]:checked ~ label {
background: rgba(var(--btaccent),1);
z-index: 2;
}

.iikmtab [type=radio]:checked ~ label ~ .iikmcontent {
z-index: 1;
}


.iikmlinks {
  width: 220px;
  height: 17px;
  padding: 5px;
  margin: 5px 0px;
  background: rgba(var(--btaccent),1);
  color: rgba(var(--ltbase),1);
  font: normal 500 14px/17px oswald; 
  display: block;
  border-radius: 3px;
  text-transform: uppercase;
  text-align: center;
}

.iikmcontent a { color: rgba(var(--ltbase),1); }

.iikmlinks:hover {
  background: rgba(var(--dnaccent),.8);
}

.iikmdate {
  padding: 5px;
  margin: 2px 5px;
  background: rgba(var(--btaccent),1);
  color: rgba(var(--ltbase),1);
  font: normal 500 14px/17px oswald; 
  display: block;
  border-radius: 3px;
  text-transform: uppercase;
  float: left;
}
